{
  "name": "wlc_ioct_set_mac",
  "confidence": "medium",
  "docstring": "Handles a WLC set-MAC ioctl by recomputing MAC-address mask state for linked interfaces and sending a set-MAC message carrying the requested P2P flag.",
  "subsystem": "mac",
  "var_renames": {
    "a2": "ioctl_cmd",
    "a3": "p2p_enable",
    "v4": "wlc_ctx",
    "v5": "mac_link_entry",
    "v7": "new_mac_low",
    "v8": "mac_high_mask",
    "v9": "mac_low_mask",
    "v10": "new_mac_high",
    "v11": "entry_mac_low",
    "v12": "entry_mac_high",
    "v16": "msg",
    "v20": "slot_index"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "linked-list pointer at the head of MAC entries or allocated message nodes"
    },
    {
      "offset": 8,
      "meaning": "message type/id field initialized to 2631 in the visible path"
    },
    {
      "offset": 12,
      "meaning": "message command/id field initialized to 2627 in the visible path"
    },
    {
      "offset": 100,
      "meaning": "MAC address low 32 bits"
    },
    {
      "offset": 104,
      "meaning": "MAC address high 16 bits"
    },
    {
      "offset": 106,
      "meaning": "ioctl command/subtype byte copied from a2"
    },
    {
      "offset": 107,
      "meaning": "list/pool slot index derived from the allocated node address"
    },
    {
      "offset": 1222,
      "meaning": "16-bit configuration/mask field set to 0x3ff"
    },
    {
      "offset": 1224,
      "meaning": "P2P enable flag copied from a3"
    }
  ]
}
